1	"use client";
2	
3	/**
4	 * PREVIEW TEMPLATE 2 — Free-tier landing (the free Minecraft server).
5	 *
6	 * Leads on the Aternos-alternative wedge — "24/7. No queue. No ads." — and puts
7	 * the signature animated element front and centre: a live-looking FREE SERVER
8	 * card that SLEEPS, then WAKES ON JOIN (a player connects → boot progress →
9	 * online with a ticking player count), looping honestly. Around it: an honest
10	 * free-vs-paid table, a tasteful free→paid upgrade teaser (the conversion
11	 * bridge), a one-click "claim your free server" CTA, and compact 5-star reviews.
12	 *
13	 * Net-new, preview-only. Self-contained hooks. Every claim matches the LIVE
14	 * /free-minecraft page (genuinely free, 1 GB, ~15s wake, sleeps idle, no queue/
15	 * ads). Respects prefers-reduced-motion. Reuses only shared brand primitives and
16	 * the `pv-*` keyframes already in globals.css — adds no CSS.
17	 */
18	
19	import Link from "next/link";
20	import { useEffect, useRef, useState } from "react";
21	import { GameLogo } from "@/components/marketing/GameLogo";
22	import { IconCheck, IconBolt, IconArrow, IconGift, IconUsers } from "@/components/marketing/icons";
23	import {
24	  CLAIM_HREF,
25	  UPGRADE_HREF,
26	  FREE_DOMAIN,
27	  SAMPLE_SUBDOMAIN,
28	  FREE_FEATURES,
29	  WEDGE,
30	  FREE_VS_PAID,
31	  UPGRADE_UNLOCKS,
32	  REVIEWS,
33	  RATING_AVG,
34	  RATING_LABEL,
35	  DISCLAIMER,
36	} from "./data";
37	
38	/* ── self-contained motion hooks ─────────────────────────────────────────── */
39	function usePrefersReducedMotion() {
40	  const [reduced, setReduced] = useState(false);
41	  useEffect(() => {
42	    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
43	    if (!mq) return;
44	    setReduced(mq.matches);
45	    const on = () => setReduced(mq.matches);
46	    mq.addEventListener?.("change", on);
47	    return () => mq.removeEventListener?.("change", on);
48	  }, []);
49	  return reduced;
50	}
51	
52	function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
53	  const ref = useRef<T | null>(null);
54	  const [seen, setSeen] = useState(false);
55	  useEffect(() => {
56	    const el = ref.current;
57	    if (!el || typeof IntersectionObserver === "undefined") {
58	      setSeen(true);
59	      return;
60	    }
61	    const io = new IntersectionObserver(
62	      ([e]) => {
63	        if (e.isIntersecting) {
64	          setSeen(true);
65	          io.disconnect();
66	        }
67	      },
68	      { threshold: 0.15, rootMargin: margin },
69	    );
70	    io.observe(el);
71	    return () => io.disconnect();
72	  }, [margin]);
73	  return { ref, seen };
74	}
75	
76	/* ── atoms ───────────────────────────────────────────────────────────────── */
77	function StarRow({ rating = 5, size = "text-sm" }: { rating?: number; size?: string }) {
78	  const filled = Math.max(0, Math.min(5, rating));
79	  return (
80	    <span className={`tracking-[0.12em] ${size}`} aria-label={`${filled} out of 5 stars`}>
81	      <span className="text-amber-300">{"★".repeat(filled)}</span>
82	      <span className="text-white/15">{"★".repeat(5 - filled)}</span>
83	    </span>
84	  );
85	}
86	
87	/* ── the signature: a free server that wakes on join ─────────────────────── */
88	type WakeState = "sleeping" | "joining" | "waking" | "online";
89	
90	const JOINERS = ["Steve", "Alex", "leo_builds", "Mia"];
91	
92	function FreeServerCard() {
93	  const reduced = usePrefersReducedMotion();
94	  const [state, setState] = useState<WakeState>("sleeping");
95	  const [pct, setPct] = useState(0);
96	  const [players, setPlayers] = useState(0);
97	  const [joiner, setJoiner] = useState(JOINERS[0]);
98	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
99	
100	  useEffect(() => {
101	    if (reduced) {
102	      // Rest on the finished, awake state — no loop, no motion.
103	      setState("online");
104	      setPct(100);
105	      setPlayers(3);
106	      return;
107	    }
108	
109	    let cancelled = false;
110	    let round = 0;
111	    const wait = (ms: number) =>
112	      new Promise<void>((res) => {
113	        const t = setTimeout(res, ms);
114	        timers.current.push(t);
115	      });
116	
117	    async function loop() {
118	      while (!cancelled) {
119	        // sleeping
120	        setState("sleeping");
121	        setPct(0);
122	        setPlayers(0);
123	        await wait(2600);
124	        if (cancelled) return;
125	
126	        // a player connects → wakes it
127	        setJoiner(JOINERS[round % JOINERS.length]);
128	        setState("joining");
129	        await wait(1500);
130	        if (cancelled) return;
131	
132	        // waking — boot progress
133	        setState("waking");
134	        for (let p = 0; p <= 100; p += 4) {
135	          if (cancelled) return;
136	          setPct(p);
137	          await wait(60);
138	        }
139	        if (cancelled) return;
140	
141	        // online — players tick in
142	        setState("online");
143	        setPlayers(1);
144	        await wait(900);
145	        if (cancelled) return;
146	        setPlayers(2);
147	        await wait(1100);
148	        if (cancelled) return;
149	        setPlayers(3);
150	        await wait(3200);
151	        round += 1;
152	      }
153	    }
154	
155	    loop();
156	    return () => {
157	      cancelled = true;
158	      timers.current.forEach(clearTimeout);
159	      timers.current = [];
160	    };
161	  }, [reduced]);
162	
163	  const awake = state === "online";
164	  const statusLabel =
165	    state === "sleeping" ? "sleeping" : state === "joining" ? "waking…" : state === "waking" ? "starting" : "online";
166	  const statusTone =
167	    state === "online"
168	      ? "bg-emerald-500/12 text-emerald-300"
169	      : state === "sleeping"
170	        ? "bg-white/[0.05] text-slate-400"
171	        : "bg-accent-cyan/12 text-accent-cyan";
172	
173	  return (
174	    <div className={reduced ? "" : "pv-float"}>
175	      <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
176	        {/* ambient accent */}
177	        <div
178	          className="pointer-events-none absolute -inset-16 -z-10 transition-opacity duration-700"
179	          style={{
180	            opacity: awake ? 0.8 : 0.3,
181	            background: "radial-gradient(45% 45% at 80% 0%, rgba(34,211,238,0.22), transparent 70%)",
182	          }}
183	          aria-hidden
184	        />
185	
186	        {/* header — address + status */}
187	        <div className="flex items-center gap-2.5 border-b border-white/[0.06] bg-white/[0.02] px-4 py-3">
188	          <GameLogo family="minecraft" size={24} />
189	          <span className="truncate font-mono text-[12px] text-slate-300">
190	            {SAMPLE_SUBDOMAIN}.{FREE_DOMAIN}
191	          </span>
192	          <span
193	            className={`ml-auto inline-flex shrink-0 items-center gap-1.5 rounded-full px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide ${statusTone}`}
194	          >
195	            <span
196	              className={`h-1.5 w-1.5 rounded-full ${awake ? "bg-emerald-400 motion-safe:animate-pulse-dot" : state === "sleeping" ? "bg-slate-500" : "bg-accent-cyan motion-safe:animate-pulse-dot"}`}
197	            />
198	            {statusLabel}
199	          </span>
200	        </div>
201	
202	        {/* world viewport — real key art, dimmed while asleep */}
203	        <div className="relative aspect-[16/10] overflow-hidden">
204	          {/* eslint-disable-next-line @next/next/no-img-element */}
205	          <img
206	            src="/games/art/minecraft_hero.jpg"
207	            alt="Minecraft world"
208	            className="h-full w-full object-cover object-center transition-all duration-700"
209	            style={{ filter: awake ? "none" : "grayscale(0.5) brightness(0.4)", transform: awake ? "scale(1.02)" : "scale(1)" }}
210	          />
211	          <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-[#080d18] via-transparent to-transparent" aria-hidden />
212	
213	          {/* state overlay */}
214	          <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center">
215	            {state === "sleeping" && (
216	              <>
217	                <span className="text-3xl" aria-hidden>💤</span>
218	                <p className="mt-2 text-sm font-semibold text-slate-200">Sleeping to save resources</p>
219	                <p className="mt-1 text-[12px] text-slate-400">A player joining wakes it in ~15 seconds.</p>
220	              </>
221	            )}
222	            {state === "joining" && (
223	              <>
224	                <span className="relative flex h-11 w-11 items-center justify-center">
225	                  <span className="absolute inset-0 rounded-full border-2 border-accent-cyan/20" />
226	                  <span className="absolute inset-0 rounded-full border-2 border-transparent border-t-accent-cyan motion-safe:animate-spin" />
227	                  <IconUsers size={18} />
228	                </span>
229	                <p className="mt-3 text-sm font-semibold text-white">
230	                  <span className="text-accent-cyan">{joiner}</span> is connecting…
231	                </p>
232	                <p className="mt-1 text-[12px] text-slate-400">Waking your server.</p>
233	              </>
234	            )}
235	            {state === "waking" && (
236	              <div className="w-full max-w-xs">
237	                <p className="text-sm font-semibold text-white">
238	                  {pct < 45 ? "Waking your server…" : pct < 85 ? "Loading world…" : "Almost there…"}
239	                </p>
240	                <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-white/10">
241	                  <div
242	                    className="h-full rounded-full bg-gradient-to-r from-accent-blue to-accent-cyan transition-[width] duration-75 ease-linear"
243	                    style={{ width: `${pct}%` }}
244	                  />
245	                </div>
246	                <p className="mt-1.5 text-right font-mono text-[11px] text-slate-400">{pct}%</p>
247	              </div>
248	            )}
249	            {state === "online" && (
250	              <>
251	                <span className="flex h-12 w-12 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300 ring-1 ring-emerald-500/30">
252	                  <IconCheck size={24} />
253	                </span>
254	                <p className="mt-3 text-base font-semibold text-white">Online &amp; ready</p>
255	                <p className="mt-1 text-[12px] text-slate-300">Connect on the standard port — no queue.</p>
256	              </>
257	            )}
258	          </div>
259	        </div>
260	
261	        {/* footer — players + spec */}
262	        <div className="flex items-center justify-between gap-3 px-4 py-3.5">
263	          <div className="flex items-center gap-2.5">
264	            <div className="flex -space-x-2">
265	              {Array.from({ length: 3 }).map((_, i) => (
266	                <span
267	                  key={i}
268	                  className="h-6 w-6 rounded-full border-2 border-[#080d18] bg-gradient-to-br from-accent-cyan to-brand-500 transition-all duration-300"
269	                  style={{ opacity: i < players ? 1 : 0.15, transform: i < players ? "scale(1)" : "scale(0.7)" }}
270	                  aria-hidden
271	                />
272	              ))}
273	            </div>
274	            <span className="font-mono text-[12px] text-slate-400 tabular-nums">
275	              {players} {players === 1 ? "player" : "players"} online
276	            </span>
277	          </div>
278	          <span className="rounded-md bg-white/[0.05] px-2 py-1 font-mono text-[11px] text-slate-400">1 GB · free</span>
279	        </div>
280	      </div>
281	
282	      {/* honest caption */}
283	      <p className="mt-3 text-center text-[11px] text-slate-500">
284	        Live demo — a real free server sleeps when empty and wakes the moment someone connects.
285	      </p>
286	    </div>
287	  );
288	}
