3	import { useEffect, useRef } from "react";
4	
5	type RGB = [number, number, number];
6	
7	function hexToRgb(hex: string): RGB {
8	  const clean = hex.replace("#", "");
9	  const full = clean.length === 3 ? clean.split("").map((c) => c + c).join("") : clean;
10	  const n = parseInt(full, 16) || 0;
11	  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
12	}
13	
14	type Particle = {
15	  x: number;
16	  y: number;
17	  vx: number;
18	  vy: number;
19	  born: number;
20	  life: number; // ms; Infinity for ambient (never expires on its own)
21	  size: number;
22	  color: RGB;
23	  drift: boolean; // ambient (wraps + twinkles) vs burst (decays + fades)
24	};
25	
26	/**
27	 * Ambient + burst particle field behind the /game-servers hero carousel.
28	 *
29	 * One canvas, one rAF loop, two populations sharing it:
30	 *  - AMBIENT: a small constant count of slow embers tinted to the active
31	 *    game's own brand colours (GAME_VISUAL's from/to), wrapping at the edges
32	 *    and twinkling — pure atmosphere, always present, never expires.
33	 *  - BURST: fired once per game change (`triggerKey` going from one value to
34	 *    a different one — never on first mount) from the carousel's own center,
35	 *    a ring of particles launched outward in all directions that decelerate
36	 *    and fade over ~1s, then get pruned. Reads as the newly-centered cover
37	 *    throwing its colour outward as it takes focus.
38	 *
39	 * Colours and the burst trigger are read live off refs inside the single rAF
40	 * loop rather than restarting the effect — so neither a colour crossfade nor
41	 * a mid-burst game change ever resets the animation or drops particles.
42	 *
43	 * `prefers-reduced-motion`: no ambient particles are seeded and no burst ever
44	 * fires — matches how GameCoverCarousel already treats reduced motion (no
45	 * autoplay, instant snaps).
46	 */
47	export function GameParticleField({
48	  colorFrom,
49	  colorTo,
50	  triggerKey,
51	}: {
52	  colorFrom: string;
53	  colorTo: string;
54	  triggerKey: string | number;
55	}) {
56	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
57	  const particlesRef = useRef<Particle[]>([]);
58	  const colorsRef = useRef<{ from: RGB; to: RGB }>({ from: hexToRgb(colorFrom), to: hexToRgb(colorTo) });
59	  const reducedRef = useRef(false);
60	  const sizeRef = useRef({ w: 0, h: 0 });
61	  const prevTriggerRef = useRef(triggerKey);
62	  const firstRunRef = useRef(true);
63	
64	  // Colours update live — the currently-drifting ambient particles simply
65	  // start mixing toward the new game's palette on their next repaint rather
66	  // than being replaced, so a game change never causes an ambient "pop".
67	  useEffect(() => {
68	    colorsRef.current = { from: hexToRgb(colorFrom), to: hexToRgb(colorTo) };
69	  }, [colorFrom, colorTo]);
70	
71	  useEffect(() => {
72	    const canvas = canvasRef.current;
73	    if (!canvas) return;
74	    const ctx = canvas.getContext("2d");
75	    if (!ctx) return;
76	
77	    reducedRef.current = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
78	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
79	
80	    const mix = (t: number): RGB => {
81	      const { from, to } = colorsRef.current;
82	      return [from[0] + (to[0] - from[0]) * t, from[1] + (to[1] - from[1]) * t, from[2] + (to[2] - from[2]) * t];
83	    };
84	
85	    const spawnAmbient = (): Particle => {
86	      const { w, h } = sizeRef.current;
87	      return {
88	        x: Math.random() * w,
89	        y: Math.random() * h,
90	        vx: (Math.random() - 0.5) * 0.14,
91	        vy: (Math.random() - 0.5) * 0.16 - 0.03,
92	        born: performance.now(),
93	        life: Infinity,
94	        size: 0.8 + Math.random() * 1.7,
95	        color: mix(Math.random()),
96	        drift: true,
97	      };
98	    };
99	
100	    const resize = () => {
101	      const rect = canvas.getBoundingClientRect();
102	      sizeRef.current = { w: rect.width, h: rect.height };
103	      canvas.width = rect.width * dpr;
104	      canvas.height = rect.height * dpr;
105	      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
106	    };
107	    resize();
108	
109	    if (!reducedRef.current) {
110	      const count = Math.min(50, Math.floor((sizeRef.current.w * sizeRef.current.h) / 8500));
111	      particlesRef.current = Array.from({ length: count }, spawnAmbient);
112	    }
113	
114	    let raf = 0;
115	    const draw = (now: number) => {
116	      const { w, h } = sizeRef.current;
117	      ctx.clearRect(0, 0, w, h);
118	      const next: Particle[] = [];
119	      for (const p of particlesRef.current) {
120	        if (p.drift) {
121	          p.x += p.vx;
122	          p.y += p.vy;
123	          if (p.x < -10) p.x = w + 10;
124	          else if (p.x > w + 10) p.x = -10;
125	          if (p.y < -10) p.y = h + 10;
126	          else if (p.y > h + 10) p.y = -10;
127	          const twinkle = 0.3 + 0.35 * Math.sin(now / 900 + p.x);
128	          ctx.beginPath();
129	          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
130	          ctx.fillStyle = `rgba(${p.color[0] | 0},${p.color[1] | 0},${p.color[2] | 0},${twinkle})`;
131	          ctx.fill();
132	          next.push(p);
133	        } else {
134	          const age = now - p.born;
135	          if (age > p.life) continue;
136	          const t = age / p.life;
137	          p.x += p.vx;
138	          p.y += p.vy;
139	          p.vx *= 0.965;
140	          p.vy *= 0.965;
141	          const alpha = (1 - t) * 0.9;
142	          const size = Math.max(0.4, p.size * (1 - t * 0.4));
143	          ctx.beginPath();
144	          ctx.arc(p.x, p.y, size, 0, Math.PI * 2);
145	          ctx.fillStyle = `rgba(${p.color[0] | 0},${p.color[1] | 0},${p.color[2] | 0},${alpha})`;
146	          ctx.fill();
147	          next.push(p);
148	        }
149	      }
150	      particlesRef.current = next;
151	      raf = requestAnimationFrame(draw);
152	    };
153	    raf = requestAnimationFrame(draw);
154	
155	    const onResize = () => resize();
156	    window.addEventListener("resize", onResize);
157	    return () => {
158	      cancelAnimationFrame(raf);
159	      window.removeEventListener("resize", onResize);
160	    };
161	    // Mount once. Colour + burst-trigger changes are read live off refs
162	    // (see the two effects below) so the canvas and its particle pool never
163	    // restart mid-animation.
164	    // eslint-disable-next-line react-hooks/exhaustive-deps
165	  }, []);
166	
167	  // Fire a burst from the carousel's own center whenever the active game
168	  // changes — never on first mount (there is nothing to transition FROM yet).
169	  useEffect(() => {
170	    if (firstRunRef.current) {
171	      firstRunRef.current = false;
172	      prevTriggerRef.current = triggerKey;
173	      return;
174	    }
175	    if (triggerKey === prevTriggerRef.current) return;
176	    prevTriggerRef.current = triggerKey;
177	    if (reducedRef.current) return;
178	    const { w, h } = sizeRef.current;
179	    if (!w || !h) return;
180	
181	    const mix = (t: number): RGB => {
182	      const { from, to } = colorsRef.current;
183	      return [from[0] + (to[0] - from[0]) * t, from[1] + (to[1] - from[1]) * t, from[2] + (to[2] - from[2]) * t];
184	    };
185	    const cx = w / 2;
186	    const cy = h / 2;
187	    const COUNT = 32;
188	    const burst: Particle[] = Array.from({ length: COUNT }, (_, i) => {
189	      const angle = (Math.PI * 2 * i) / COUNT + (Math.random() - 0.5) * 0.4;
190	      const speed = 1.5 + Math.random() * 2.6;
191	      return {
192	        x: cx,
193	        y: cy,
194	        vx: Math.cos(angle) * speed,
195	        vy: Math.sin(angle) * speed,
196	        born: performance.now(),
197	        life: 700 + Math.random() * 350,
198	        size: 1.6 + Math.random() * 2.4,
199	        color: mix(Math.random()),
200	        drift: false,
201	      };
202	    });
203	    particlesRef.current = [...particlesRef.current, ...burst];
204	  }, [triggerKey]);
205	
206	  return <canvas ref={canvasRef} aria-hidden className="pointer-events-none absolute inset-0 h-full w-full" />;
207	}
