3	/**
4	 * Shared client-side kit for the three preview game-landing directions.
5	 * Small, dependency-free hooks + presentational atoms so each direction stays
6	 * focused on its own layout/motion identity. Everything here respects
7	 * prefers-reduced-motion: motion hooks resolve to their final resting value.
8	 */
9	
10	import { useEffect, useRef, useState } from "react";
11	import type { IconKey } from "./data";
12	import {
13	  IconBolt,
14	  IconApps,
15	  IconTerminal,
16	  IconShield,
17	  IconGauge,
18	  IconUsers,
19	  IconBackup,
20	  IconGlobe,
21	  IconScale,
22	} from "@/components/marketing/icons";
23	
24	/* ── hooks ─────────────────────────────────────────────────────────────── */
25	
26	export function usePrefersReducedMotion() {
27	  const [reduced, setReduced] = useState(false);
28	  useEffect(() => {
29	    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
30	    if (!mq) return;
31	    setReduced(mq.matches);
32	    const on = () => setReduced(mq.matches);
33	    mq.addEventListener?.("change", on);
34	    return () => mq.removeEventListener?.("change", on);
35	  }, []);
36	  return reduced;
37	}
38	
39	/** Fires once when the element first scrolls into view. */
40	export function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
41	  const ref = useRef<T | null>(null);
42	  const [seen, setSeen] = useState(false);
43	  useEffect(() => {
44	    const el = ref.current;
45	    if (!el || typeof IntersectionObserver === "undefined") {
46	      setSeen(true);
47	      return;
48	    }
49	    const io = new IntersectionObserver(
50	      ([e]) => {
51	        if (e.isIntersecting) {
52	          setSeen(true);
53	          io.disconnect();
54	        }
55	      },
56	      { threshold: 0.15, rootMargin: margin },
57	    );
58	    io.observe(el);
59	    return () => io.disconnect();
60	  }, [margin]);
61	  return { ref, seen };
62	}
63	
64	/**
65	 * Smoothly counts a number up to `target` once `active`. Under reduced motion
66	 * it returns the target immediately.
67	 */
68	export function useCountUp(target: number, active: boolean, duration = 1100, reduced = false) {
69	  const [val, setVal] = useState(reduced ? target : 0);
70	  useEffect(() => {
71	    if (!active) return;
72	    if (reduced) {
73	      setVal(target);
74	      return;
75	    }
76	    let raf = 0;
77	    const start = performance.now();
78	    const tick = (now: number) => {
79	      const t = Math.min(1, (now - start) / duration);
80	      const eased = 1 - Math.pow(1 - t, 3);
81	      setVal(Math.round(target * eased));
82	      if (t < 1) raf = requestAnimationFrame(tick);
83	    };
84	    raf = requestAnimationFrame(tick);
85	    return () => cancelAnimationFrame(raf);
86	  }, [target, active, duration, reduced]);
87	  return val;
88	}
89	
90	/**
91	 * A "live" integer that idles around a base value with small jitter, evoking a
92	 * ticking player count / TPS readout. Static (base) under reduced motion.
93	 */
94	export function useJitter(base: number, swing: number, active: boolean, ms = 2600, reduced = false) {
95	  const [val, setVal] = useState(base);
96	  useEffect(() => {
97	    if (!active || reduced) {
98	      setVal(base);
99	      return;
100	    }
101	    const id = window.setInterval(() => {
102	      if (document.hidden) return;
103	      const delta = Math.round((Math.random() - 0.45) * swing);
104	      setVal((v) => Math.max(base - swing, Math.min(base + swing, v + delta)));
105	    }, ms);
106	    return () => window.clearInterval(id);
107	  }, [base, swing, active, ms, reduced]);
108	  return val;
109	}
