import type { Metadata } from "next";
import { FreeTierTemplate } from "@/components/marketing/freetiertemplate/FreeTierTemplate";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { APP_URL, FaqJsonLd } from "@/components/marketing/StructuredData";
import { CLAIM_HREF, FREE_FAQ, FREE_DOMAIN, SAMPLE_SUBDOMAIN } from "@/components/marketing/freetiertemplate/data";

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps.
export const metadata: Metadata = {
  title: "Preview · Free-tier template (Free Minecraft)",
  description:
    "A genuinely free Minecraft server on your own subdomain — 1 GB RAM, wakes on join in ~15s, sleeps when idle. No queue, no ads, no credit card.",
  robots: { index: false, follow: false },
};

// Product/Offer for the free tier. It is genuinely $0, so we emit a single
// zero-price Offer directly (the shared ProductOffersJsonLd drops non-positive
// prices, which is correct for paid lines but would suppress this real free one).
const productJsonLd = {
  "@context": "https://schema.org",
  "@type": "Product",
  name: "Free Minecraft Server Hosting",
  description: `A genuinely free Minecraft server on your own subdomain at ${SAMPLE_SUBDOMAIN}.${FREE_DOMAIN}. 1 GB RAM, wakes on join in ~15 seconds, sleeps when idle — no queue, no ads, no credit card.`,
  brand: { "@type": "Brand", name: "Nxeon" },
  offers: {
    "@type": "Offer",
    name: "Free tier",
    price: "0",
    priceCurrency: "USD",
    availability: "https://schema.org/InStock",
    url: `${APP_URL}${CLAIM_HREF}`,
  },
};

export default function Page() {
  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(productJsonLd) }}
      />
      <FaqJsonLd items={FREE_FAQ} />
      <FreeTierTemplate reviewBadges={<ReviewBadges />} />
    </>
  );
}

