import type { Metadata } from "next";
import { ModsTemplate } from "@/components/marketing/modstemplate/ModsTemplate";
import { MODS_CONTENT } from "@/components/marketing/modstemplate/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { APP_URL, ProductOffersJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps.
export const metadata: Metadata = {
  title: "Preview · Game-mods page template",
  description:
    "Full SFTP, an in-dashboard file manager, and live console access on every Nxeon game server — install anything your game's modding platform supports. Five games also get a genuine one-click Mod Store.",
  robots: { index: false, follow: false },
};

// Real per-game plan prices (from the live game-servers directory) so the
// AggregateOffer never advertises a price we don't charge.
const MOD_OFFERS = [
  { name: "Minecraft server hosting", price: 4.99 },
  { name: "CS2 server hosting", price: 6.99 },
  { name: "Valheim server hosting", price: 9.99 },
  { name: "Rust server hosting", price: 12.99 },
  { name: "Palworld server hosting", price: 14.99 },
];

export default function Page() {
  return (
    <>
      <ProductOffersJsonLd
        name="Nxeon Game Server Hosting — Full Mod & File Access"
        description="Every Nxeon game server ships with full SFTP, an in-dashboard file manager, and live console access, so you can install anything your game's modding platform supports. Minecraft, Rust, CS2, Valheim, and Palworld also include a genuine one-click Mod Store."
        url={`${APP_URL}/game-servers`}
        offers={MOD_OFFERS}
      />
      <FaqJsonLd items={MODS_CONTENT.faq} />
      <ModsTemplate content={MODS_CONTENT} reviewBadges={<ReviewBadges />} />
    </>
  );
}
